refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     max ora lancia un ValueError in caso di errore;
     in precedenza veniva restituito &false; e veniva emesso un errore E_WARNING.




    8.0.0

     Poiché i 
     confronti tra stringhe e numeri sono stati modificati,
     max non restituisce più un
     valore diverso in base all'ordine degli argomenti in questi casi.

  &reftitle.examples;



    Esempi di utilizzo di max


<?php
echo max(2, 3, 1, 6, 7), PHP_EOL;  // 7
echo max(array(2, 4, 5)), PHP_EOL; // 5

// 'ciao' è una stringa non numerica, quindi -1 viene convertito nella stringa "-1" e i
// valori vengono confrontati come stringhe: "ciao" è maggiore di "-1"
echo max('ciao', -1), PHP_EOL;    // ciao

// Con più array di lunghezze diverse, max restituisce il più lungo
$val = max(array(2, 2, 2), array(1, 1, 1, 1)); // array(1, 1, 1, 1)
var_dump($val);

// Più array della stessa lunghezza vengono confrontati da sinistra a destra
// quindi nell'esempio: 2 == 2, ma 5 > 4
$val = max(array(2, 4, 8), array(2, 5, 1)); // array(2, 5, 1)
var_dump($val);

// Se vengono forniti sia un array sia un non-array, verrà restituito l'array
// poiché i confronti considerano gli array maggiori di qualsiasi altro valore
$val = max('stringa', array(2, 5, 7), 42);   // array(2, 5, 7)
var_dump($val);

// Se un argomento è NULL o un booleano, verrà confrontato con
// gli altri valori usando la regola FALSE < TRUE indipendentemente dagli altri tipi coinvolti
// Nell'esempio seguente, -10 viene trattato come TRUE nel confronto
$val = max(-10, FALSE); // -10
var_dump($val);

// 0, invece, viene trattato come FALSE, quindi è "minore di" TRUE
$val = max(0, TRUE); // TRUE
var_dump($val);
?>
